// Seed roles and assign users
public async Task SeedRolesAsync(IServiceProvider services)
{
    var roleManager = services.GetRequiredService<RoleManager<IdentityRole>>();
    await roleManager.CreateAsync(new IdentityRole("Admin"));
    await roleManager.CreateAsync(new IdentityRole("Manager"));
    await roleManager.CreateAsync(new IdentityRole("User"));
}

// Controller
[ApiController]
[Route("api/[controller]")]
public class AdminController : ControllerBase
{
    // Only admins
    [HttpGet("users")]
    [Authorize(Roles = "Admin")]
    public IActionResult GetAllUsers() => Ok(_userManager.Users.ToList());

    // Admin or Manager
    [HttpPost("reports")]
    [Authorize(Roles = "Admin,Manager")]
    public IActionResult CreateReport(ReportRequest request) => Ok();

    // Multiple role requirements
    [Authorize(Policy = "RequireAdminOrManager")]
    public IActionResult AccessRestrictedArea() => Ok();
}

